import java.util.*;

import org.junit.jupiter.api.*;

import static org.junit.jupiter.api.Assertions.*;

public class Main {
    public static void main(String[] args) {
        JalankanTest.kelas(OngkirTest.class);
    }
}

@DisplayName("Ongkos kirim")
class OngkirTest {
    @Nested
    @DisplayName("dalam kota")
    class DalamKota {
        @Test
        @DisplayName("tarif tetap 10000")
        void dalamKotaTetap() {
            assertEquals(10000, Ongkir.hitung("dalam kota", 1));
        }

        @Test
        @DisplayName("berat tidak berpengaruh")
        void dalamKotaBeratTidakBerpengaruh() {
            assertEquals(10000, Ongkir.hitung("dalam kota", 5));
        }
    }

    @Nested
    @DisplayName("luar kota")
    class LuarKota {
        @Test
        @DisplayName("15000 per kilo")
        void luarKotaPerKilo() {
            assertEquals(30000, Ongkir.hitung("luar kota", 2));
        }
    }
}

class Ongkir {
    static int hitung(String tujuan, int kilo) {
        if (tujuan.equals("dalam kota")) {
            return 10000;
        }
        return 15000 * kilo;
    }
}
